function validate([s, queryCharacters, queryIndices]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 100000 characters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase letters.';
  if (typeof queryCharacters !== 'string' || !/^[a-z]+$/.test(queryCharacters) || queryCharacters.length > 100000) return 'queryCharacters needs 1 to 100000 lowercase letters.';
  if (queryIndices.length !== queryCharacters.length) return 'queryIndices and queryCharacters must have the same length.';
  if (queryIndices.some(i => !Number.isInteger(i) || i < 0 || i >= s.length)) return 'Each query index must be a position in s.';
  return null;
}

