function longestRepeating(s, queryCharacters, queryIndices) {
  const n = s.length;
  const chars = s.split('');
  const prefix = new Array(4 * n).fill(0);
  const suffix = new Array(4 * n).fill(0);
  const best = new Array(4 * n).fill(0);

  const pull = (node, lo, hi) => {
    const mid = (lo + hi) >> 1;
    const left = 2 * node;
    const right = 2 * node + 1;
    const joins = chars[mid] === chars[mid + 1];
    prefix[node] = prefix[left];
    if (joins && prefix[left] === mid - lo + 1) prefix[node] += prefix[right];
    suffix[node] = suffix[right];
    if (joins && suffix[right] === hi - mid) suffix[node] += suffix[left];
    best[node] = Math.max(best[left], best[right]);
    if (joins) best[node] = Math.max(best[node], suffix[left] + prefix[right]);
  };

  const build = (node, lo, hi) => {
    if (lo === hi) {
      prefix[node] = 1;
      suffix[node] = 1;
      best[node] = 1;
      return;
    }
    const mid = (lo + hi) >> 1;
    build(2 * node, lo, mid);
    build(2 * node + 1, mid + 1, hi);
    pull(node, lo, hi);
  };

  const update = (node, lo, hi, index) => {
    if (lo === hi) return;
    const mid = (lo + hi) >> 1;
    if (index <= mid) update(2 * node, lo, mid, index);
    else update(2 * node + 1, mid + 1, hi, index);
    pull(node, lo, hi);
  };

  build(1, 0, n - 1);
  const lengths = [];
  for (let i = 0; i < queryIndices.length; i++) {
    chars[queryIndices[i]] = queryCharacters[i];
    update(1, 0, n - 1, queryIndices[i]);
    lengths.push(best[1]);
  }
  return lengths;
}

