function longestRepeating(s, queryCharacters, queryIndices) {
  const letters = [...s];
  const out = [];
  for (let q = 0; q < queryIndices.length; q++) {
    letters[queryIndices[q]] = queryCharacters[q];
    let longest = 0;
    for (let start = 0; start < letters.length; start++) {
      let end = start;
      while (end < letters.length && letters[end] === letters[start]) end++;
      longest = Math.max(longest, end - start);
    }
    out.push(longest);
  }
  return out;
}

