function generate(rand, size) {
  const large = size === 'large';
  const letters = large ? (rand() < 0.6 ? 2 : 26) : 1 + Math.floor(rand() * 3);
  const n = large ? 6000 : 1 + Math.floor(rand() * 9);
  const k = large ? 2000 : 1 + Math.floor(rand() * 6);
  const letter = () => String.fromCharCode(97 + Math.floor(rand() * letters));
  let s = '';
  // Large strings are built from runs so that long repeated stretches exist and get split and merged.
  while (s.length < n) s += letter().repeat(large ? 1 + Math.floor(rand() * 40) : 1);
  s = s.slice(0, n);
  let queryCharacters = '';
  const queryIndices = [];
  for (let i = 0; i < k; i++) {
    queryCharacters += letter();
    queryIndices.push(Math.floor(rand() * n));
  }
  return [s, queryCharacters, queryIndices];
}
